#include "(CurrentProject)/vTools/db/tableInfo.js"
#include "(CurrentProject)/vTools/utils.js"



var cbCampos = theRoot.dataView().control( "CAMPOS" );
var cbCondicion = theRoot.dataView().control( "CONDICION" );
var fieldInfo = JSON.parse(cbCampos.itemData( cbCampos.currentIndex ));
var bCampoCompleto = theRoot.varToBool("CAMPO_COMPLETO");
var bDistinguirMayusMinus = theRoot.varToBool("CMP_DIST_MAYUS_MINUS") && theRoot.dataView().control("CMP_DIST_MAYUS_MINUS").enabled;
var compararFichaSel = theRoot.varToBool("CMP_FICHA_SEL") && theRoot.dataView().control("CMP_FICHA_SEL").enabled;

