var lista = new VRegisterList(theRoot);
var listaDestino = new VRegisterList(theRoot);

var listaTextoDestino = new VByteArray();
listaTextoDestino.setText(theRoot.varToString("LISTA"));
listaTextoDestino.fromBase64(listaTextoDestino);
lista.loadFromData(listaTextoDestino);
if (listaDestino.loadFromData(listaTextoDestino))
	listaDestino.clear();

//var valorABuscar;
var tipoComparacion = 0;  // 0: numerica   1: cadena    2: Fecha    3: Hora   4: Tiempo   5: Bool


// Obtenemos el valor a comparar del control mostrado en función a si el campo donde se introduce el valor a buscar está visible
if (theRoot.dataView().control("VALOR_NUMERICO").visible) {
	var valorABuscar = theRoot.dataView().control("VALOR_NUMERICO").value;
	tipoComparacion = 0;
}

if (theRoot.dataView().control("VALOR_STRING").visible) {
	var valorABuscar = theRoot.dataView().control("VALOR_STRING").text;
	tipoComparacion = 1;
}
if (theRoot.dataView().control("VALOR_MAESTRO").visible) {
	cbValorMaestro = theRoot.dataView().control("VALOR_MAESTRO");
	var valorABuscar = cbValorMaestro.itemData(cbValorMaestro.currentIndex);
	if (fieldInfo.bindType==VTableInfo.BindTypeStatic) {
		// Si es una tabla estática el código puede ser alfa, así que comparamos de tipo cadena
		tipoComparacion = 1
		// Ajustamos el valor de otros controles para que la comparación que s ehace más adelante sea la correcta
		bDistinguirMayusMinus = true;
		bCampoCompleto = false;
	} else
		tipoComparacion = 0;
}
if (theRoot.dataView().control("VALOR_FECHA").visible) {
	tipoComparacion = 2;
	if (""==theRoot.dataView().control("VALOR_FECHA").text) {
		var valorABuscar = new Date(0).toISOString();
	} else {
		var valorABuscar = new Date();
		valorABuscar = theRoot.dataView().control("VALOR_FECHA").date;
		valorABuscar = valorABuscar.toISOString();
	}
}	

if (theRoot.dataView().control("VALOR_HORA").visible) {
	var valorABuscar = new Date();
	valorABuscar = theRoot.dataView().control("VALOR_HORA").dateTime;
	valorABuscar = valorABuscar.toISOString();
	tipoComparacion = 3;
}

if (theRoot.dataView().control("VALOR_TIEMPO").visible) {
	var valorABuscar = new Date();
	valorABuscar = theRoot.dataView().control("VALOR_TIEMPO").dateTime;
	valorABuscar = valorABuscar.toISOString();
	tipoComparacion = 4;
}

if (theRoot.dataView().control("VALOR_BOOL").visible) {
	var valorABuscar = theRoot.dataView().control("VALOR_BOOL").currentIndex;
	tipoComparacion = 5;
}

// Si hemos seleccionado comparar con la ficha seleccionada averiguamos el valor del campo a buscar para la ficha seleccionada
if (compararFichaSel) {
	var registro = new VRegister();
	//registro = lista.readAt(control.currentSelect());
	registro = lista.readAt(theRoot.varToInt("POS_LISTA"));
	switch (tipoComparacion) {
		case 0: // Numerico
				valorABuscar = registro.fieldToInt(fieldInfo.id);
				break;
		case 1: // Cadena
				valorABuscar = registro.fieldToString(fieldInfo.id);
				break;
		case 2: // Fecha
				if (""==registro.fieldToString(fieldInfo.id)) {
					var valorABuscar = new Date(0).toISOString();
				} else {
					var valorABuscar = new Date();
					valorABuscar = registro.fieldToDate(fieldInfo.id);
					valorABuscar = valorABuscar.toISOString();
				}
				break;
		case 3: // Hora
				var valorABuscar = new Date();
				valorABuscar = registro.fieldToTime(fieldInfo.id);
				valorABuscar = valorABuscar.toISOString();
				break;
		case 4: // Tiempo
				var valorABuscar = new Date();
				valorABuscar = registro.fieldToDateTime(fieldInfo.id);
				valorABuscar = valorABuscar.toISOString();
				break;
		case 5: // Bool
				valorABuscar = registro.fieldToBool(fieldInfo.id);
				break;
	}

}

// Mostramos la barra de progreso
var pb = theRoot.dataView().control("PB");
pb.show();
pb.reset();
pb.setMaximum(lista.size());
// En la parte data de los items del combo tenemos un carácter indicando el operador  a usar en la comparación
var operador = cbCondicion.itemData(cbCondicion.currentIndex);
for (var i=0;i<lista.size();i++) {
	registro = lista.readAt(i);
	// Obtenemos el valor a comparar con la función correspondiente al tipo de campo
	switch (tipoComparacion) {
		case 0: // Numerico
				valorCampo = registro.fieldToInt(fieldInfo.id);
				break;
		case 1: // Cadena
				valorCampo = registro.fieldToString(fieldInfo.id);
				break;
		case 2: // Fecha
				if (""==registro.fieldToString(fieldInfo.id)) {
					var valorCampo = new Date(0).toISOString();
				} else {
					var valorCampo = new Date();
					valorCampo = registro.fieldToDate(fieldInfo.id);
					valorCampo = valorCampo.toISOString();
				}
				break;
		case 3: // Time
				var valorCampo = new Date();
				valorCampo = registro.fieldToTime(fieldInfo.id);
				valorCampo = valorCampo.toISOString();
				break;
		case 4: // Tiempo
				var valorCampo = new Date();
				valorCampo = registro.fieldToDateTime(fieldInfo.id);
				valorCampo = valorCampo.toISOString();
				break;
		case 5: // Bool
				valorCampo = registro.fieldToBool(fieldInfo.id);
				break;
	}
	// Hacemos la comparación en función al operador y lo añadimos a la lista destino si se cumple la condición
	switch (operador) {
		case "=":	if (tipoComparacion==1) { // Cadena
						// Si no queremos distinguir entre mayúsculas y minúsculas pasamos los dos valores a mayúsculas
						if (!bDistinguirMayusMinus) {
							valorABuscar = valorABuscar.toUpperCase();
							valorCampo = valorCampo.toUpperCase();
						}
						// Si queremos comparar con el campo completo lo comparamos todo a todo
						if (bCampoCompleto) {
							if (valorCampo == valorABuscar)
								listaDestino.append(registro);
						} else 
							// Si no es campo completo lo hacemos buscando una cadena dentro de otra
							if (valorCampo.indexOf(valorABuscar)>-1)
								listaDestino.append(registro);
					} else {
						if (valorCampo==valorABuscar)
							listaDestino.append(registro);
					}
					break;
		case "!":	if (tipoComparacion==1) { // Cadena
						// Si no queremos distinguir entre mayúsculas y minúsculas pasamos los dos valores a mayúsculas
						if (!bDistinguirMayusMinus) {
							valorABuscar = valorABuscar.toUpperCase();
							valorCampo = valorCampo.toUpperCase();
						}
						// Si queremos comparar con el campo completo lo comparamos todo a todo
						if (bCampoCompleto) {
							if (valorCampo != valorABuscar)
								listaDestino.append(registro);
						} else 
							// Si no es campo completo nos aseguramos de que la cadena a buscar no exista dentro de la cadena del registro actual
							if (valorCampo.indexOf(valorABuscar) == -1)
								listaDestino.append(registro);
					} else if (valorCampo != valorABuscar)
						listaDestino.append(registro);
					break;
		case "<":	if (valorCampo<valorABuscar)
						listaDestino.append(registro);
					break;
		case ">":	if (valorCampo>valorABuscar)
						listaDestino.append(registro);
					break;			
	}
	pb.setValue(i);
}

// Retornamos la lista resultante en Base64 dentro de la variable LISTA
listaTextoDestino = listaDestino.saveToData();
listaTextoDestino = listaTextoDestino.toBase64();
theRoot.setVar("LISTA", listaTextoDestino.toLatin1String());
// Cerramos el formulario
theRoot.dataView().closeForm();

#include "(CurrentProject)/vTools/listas/filtrar/filtrar.js"
#include "(CurrentProject)/vTools/db/tableInfo.js"
#include "(CurrentProject)/vTools/utils.js"

// Se lee el valor del combo campo
var cbCampos = theRoot.dataView().control( "CAMPOS" );
var cbCondicion = theRoot.dataView().control( "CONDICION" );
// Obtenemos la información del campo seleccionado
var fieldInfo = JSON.parse(cbCampos.itemData( cbCampos.currentIndex ));

// En función al campo seleccionado ajustamos la visibilidad de los controles y el contenido de las condiciones. En el caso de maestros se rellena el combo de valores con los valores que aparecen en la lista
filtrar.adjustControls(theRoot.dataView(), fieldInfo);
cbCondicion.currentIndex=0;

// Deshabilitamos o no los controles de entrada de valor si está activo el comparar con ficha seleccionada
var activo = theRoot.varToBool("CMP_FICHA_SEL");
theRoot.dataView().control("VALOR_NUMERICO").setEnabled(!activo);
theRoot.dataView().control("VALOR_STRING").setEnabled(!activo);
theRoot.dataView().control("VALOR_FECHA").setEnabled(!activo);
theRoot.dataView().control("VALOR_HORA").setEnabled(!activo);
theRoot.dataView().control("VALOR_TIEMPO").setEnabled(!activo);
theRoot.dataView().control("VALOR_BOOL").setEnabled(!activo);

#include "(CurrentProject)/vTools/listas/filtrar/filtrar.js"
#include "(CurrentProject)/vTools/db/tableInfo.js"
#include "(CurrentProject)/vTools/utils.js"

// Sólo se añaden al combo de campos filtrables los que sean de estos tipos
var validFieldTypes = [VTableInfo.FieldTypeAlpha256, VTableInfo.FieldTypeAlpha128, VTableInfo.FieldTypeAlpha64,
	VTableInfo.FieldTypeAlpha40, VTableInfo.FieldTypeAlphaLatin1, VTableInfo.FieldTypeAlphaUtf16,
	VTableInfo.FieldTypeNumeric, VTableInfo.FieldTypeDate, VTableInfo.FieldTypeTime, VTableInfo.FieldTypeDateTime,
	VTableInfo.FieldTypeBool, VTableInfo.FieldTypeFormulaNumeric, VTableInfo.FieldTypeFormulaAlfa, 
	VTableInfo.FieldTypeFormulaDate, VTableInfo.FieldTypeFormulaDateTime];

// Sacamos la lista de elementos en Base64 de la variable LISTA 
var lista = new VRegisterList(theRoot);
var listaTexto = new VByteArray();
listaTexto.setText(theRoot.varToString("LISTA"));
listaTexto.fromBase64(listaTexto);
if (lista.loadFromData(listaTexto)) {
	// Obtenemos la tableInfo de esa lista
	var tableInfo = lista.tableInfo();
	// Obtenemos un array con varias propiedades de los campos de esa tabla para incluirlos en el combo de campos filtrables
	var fieldsInfo = getFieldsInformation(tableInfo);

	if (fieldsInfo.length) {
		var cbCampos = theRoot.dataView().control("CAMPOS");
		var cbCondicion = theRoot.dataView().control( "CONDICION" );
		if (cbCampos) {
			cbCampos.clear();
			for (var i=0; i<fieldsInfo.length; i++)
				// Agregamos los campos de los tipos indicados y que no sean privados
				if ((validFieldTypes.indexOf(fieldsInfo[i].type)>-1) && (!fieldsInfo[i].private))
					// Si es un campo valido para realizar filtrado lo añadimos junto con la información del campo que usaremos más adelante
					cbCampos.addItem(fieldsInfo[i].name, JSON.stringify(fieldsInfo[i]));
		}
	}
	// Si hay campos que filtrar
	if (cbCampos.count) {
		// Ocultamos la barra de progreso
		theRoot.dataView().control("PB").hide();
		var fieldInfo = JSON.parse(cbCampos.itemData( cbCampos.currentIndex ));
		filtrar.adjustControls(theRoot.dataView(), fieldInfo);
		cbCondicion.currentIndex=0;
		theRoot.dataView().control("CMP_COMPLETO").setChecked(1);
		theRoot.dataView().control("CMP_DIST_MAYUS_MINUS").setChecked(0);
	} else {
		alert(tr("93t4hhss.vca/ERR_NO_CAMP"));
		theRoot.dataView().closeForm();
	}
}
